+
+.badge-out-of-stock {
+    display: inline-block;
+    padding: 0.2rem 0.5rem;
+    background: #dc3545;
+    color: white;
+    font-size: 0.75rem;
+    border-radius: 4px;
+    margin-bottom: 0.5rem;
+}
+
+.btn-add-to-cart {
+    width: 100%;
+    padding: 0.5rem;
+    background: #0d6efd;
+    color: white;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-add-to-cart:hover:not(:disabled) {
+    background: #0b5ed7;
+}
+
+.btn-add-to-cart:disabled {
+    background: #6c757d;
+    cursor: not-allowed;
+}
+
+/* Pagination */
+.catalog-pagination {
+    display: flex;
+    justify-content: center;
+    gap: 0.4rem;
+    margin-top: 1.5rem;
+}
+
+.btn-page {
+    padding: 0.4rem 0.75rem;
+    border: 1px solid #dee2e6;
+    background: white;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-page:hover:not(:disabled) {
+    background: #e9ecef;
+}
+
+.btn-page.active {
+    background: #0d6efd;
+    color: white;
+    border-color: #0d6efd;
+}
+
+.btn-page:disabled {
+    color: #adb5bd;
+    cursor: not-allowed;
+}
+
+/* States */
+.loading-indicator,
+.error-message,
+.empty-results {
+    text-align: center;
+    padding: 3rem 1rem;
+    color: #6c757d;
+}
+
+.error-message {
+    color: #dc3545;
+}
+
+.error-message button {
+    margin-top: 0.75rem;
+    padding: 0.5rem 1rem;
+    background: #dc3545;
+    color: white;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+

